export function matchLabs(labs,query){const q=normalizeSearch(query);return labs.filter(lab=>normalizeSearch(`${lab.title} ${lab.category} ${lab.question} ${learning[lab.id]?.join(' ')||''}`).includes(q));}
export function cleanProgress(raw,allowed){
 const result={records:{},last:null};if(!raw||typeof raw!=='object')return result;
 if(raw.records&&typeof raw.records==='object')for(const id of allowed){const r=raw.records[id];if(r&&typeof r==='object'&&r.discovered===true)result.records[id]={discovered:true,note:typeof r.note==='string'?r.note.slice(0,280):''};}
 if(raw.last&&allowed.includes(raw.last.lab))result.last={lab:raw.last.lab,journey:journeys.some(j=>j.id===raw.last.journey)?raw.last.journey:null};
 return result;
}
